File.WriteAllText("log.txt", "Start\n");
File.AppendAllText("log.txt", "Test 1 ok\n");
File.AppendAllText("log.txt", "Test 2 ok\n");

string inhalt = File.ReadAllText("log.txt");
Console.Write(inhalt);
// Ausgabe:
// Start
// Test 1 ok
// Test 2 ok

string[] daten =
    { "Lena;1", "Jonas;3", "Mia;2" };
File.WriteAllLines("noten.csv", daten);

string[] zeilen =
    File.ReadAllLines("noten.csv");
int summe = 0;
foreach (string zeile in zeilen)
{
    string[] teile = zeile.Split(';');
    string name = teile[0];
    int note = int.Parse(teile[1]);
    Console.WriteLine($"{name}: {note}");
    summe += note;
}
int schnitt = summe / zeilen.Length;
Console.WriteLine($"Schnitt: {schnitt}");
// Ausgabe:
// Lena: 1
// Jonas: 3
// Mia: 2
// Schnitt: 2

using (StreamWriter writer =
       new StreamWriter("einkauf.txt"))
{
    writer.WriteLine("Milch");
    writer.WriteLine("Brot");
    writer.WriteLine("Äpfel");
}   // Datei wird hier geschlossen

using (StreamReader reader =
       new StreamReader("einkauf.txt"))
{
    int nr = 1;
    while (!reader.EndOfStream)
    {
        string zeile = reader.ReadLine();
        Console.WriteLine($"{nr}. {zeile}");
        nr++;
    }
}
// Ausgabe:
// 1. Milch
// 2. Brot
// 3. Äpfel

string pfad = "highscore.txt";
